function home_error($message, $status=400) { http_response_code($status); echo json_encode(['error'=>$message]); exit; }
function home_url($value) { $value=trim((string)$value); if ($value==='' || (filter_var($value,FILTER_VALIDATE_URL) && in_array(strtolower(parse_url($value,PHP_URL_SCHEME)),['http','https'],true))) return $value; home_error('Links must be valid HTTP or HTTPS URLs.'); }
function home_upload($field,$dir) { if (empty($_FILES[$field]) || $_FILES[$field]['error']===UPLOAD_ERR_NO_FILE) return ''; if ($_FILES[$field]['error']!==UPLOAD_ERR_OK || $_FILES[$field]['size']>8*1024*1024) home_error('Images must be up to 8 MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$field]['tmp_name']); $types=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp']; if(!isset($types[$mime])) home_error('Only JPG, PNG, GIF, and WEBP images are allowed.'); if(!is_dir($dir)) mkdir($dir,0755,true); $name=bin2hex(random_bytes(12)).'.'.$types[$mime]; if(!move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$name)) home_error('Unable to upload image.',500); return 'uploads/home/'.$name; }
function home_defaults() { return ['slides'=>[['id'=>1,'title'=>'Homepage image 1','image_url'=>'https://i.imgur.com/4NGCY31.jpeg','sort_order'=>1,'is_active'=>true],['id'=>2,'title'=>'Homepage image 2','image_url'=>'https://i.imgur.com/jmNXZxc.jpeg','sort_order'=>2,'is_active'=>true],['id'=>3,'title'=>'Homepage image 3','image_url'=>'https://i.imgur.com/Vh5sp4J.jpeg','sort_order'=>3,'is_active'=>true]],'ticker'=>[['id'=>1,'title'=>'UNDP Philippines - 2026 Circular Solutions: Innovation Challenge and CSO Grants','date'=>'June 17, 2026','link_url'=>'https://www.facebook.com/share/p/18yBEeKCHQ/','is_active'=>true]],'central'=>[['id'=>1,'title'=>"DILG Statement on the BJMP's Custody of Senator Rodante Dizon Marcoleta",'date'=>'July 15, 2026','description'=>"The Department of the Interior and Local Government (DILG), through the Bureau of Jail Management and Penology (BJMP), confirms its commitment to lawful, impartial, and professional custodial service.",'link_url'=>'https://www.dilg.gov.ph/news-archive/','sort_order'=>1,'is_active'=>true]],'provincial'=>[['id'=>1,'title'=>'Provincial Rural Improvement Club (PRIC) 2nd Quarter Meeting','date'=>'June 30, 2026','description'=>'The Office of the Provincial Agriculturist convened the Provincial Rural Improvement Club 2nd Quarter Meeting in Tandag City.','image_url'=>'Logos/PRIC 2ND QUARTER MEETING (1).png','link_url'=>'https://surigaodelsur.gov.ph/news-single/550','sort_order'=>1,'is_active'=>true]],'featured'=>[['id'=>1,'title'=>'Featured news','date'=>'July 21, 2026','description'=>'The Department of the Interior and Local Government (DILG) Surigao del Sur conducted a three-day workshop on the formulation of the 2026–2028 Peace and Order and Public Safety Plan.','image_url'=>'https://picsum.photos/seed/featured/1200/700','link_url'=>'https://www.dilg.gov.ph/whatsnew-archive/','sort_order'=>1,'is_active'=>true]]]; }
function home_load($file,$dir) { if(!is_dir($dir)) mkdir($dir,0755,true); if(!file_exists($file)) { $data=home_defaults(); file_put_contents($file,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX); return $data; } $data=json_decode(file_get_contents($file),true); return is_array($data)?$data:home_defaults(); }
function home_save($file,$data) { if(file_put_contents($file,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)===false) home_error('Unable to save homepage content.',500); }
 $data=home_load($dataFile,$dataDir); if($_SERVER['REQUEST_METHOD']==='GET') { $requestedGroup = $_GET['group'] ?? null; if($requestedGroup !== null) { if(!isset($data[$requestedGroup])||!in_array($requestedGroup,['slides','ticker','central','provincial','featured'],true)) home_error('Invalid homepage content group.'); $payload = [$requestedGroup => $data[$requestedGroup]]; foreach($payload as &$groupRows) usort($groupRows,function($a,$b){return ((int)($a['sort_order']??0))<=>((int)($b['sort_order']??0));}); unset($groupRows); $isAdmin=!empty($_SESSION['user_id'])&&($_SESSION['role']??'')==='ADMIN'; if(!$isAdmin){ foreach($payload as &$groupRows) $groupRows=array_values(array_filter($groupRows,function($row){return !empty($row['is_active']);})); unset($groupRows);} echo json_encode($payload); exit; } foreach($data as &$group) usort($group,function($a,$b){return ((int)($a['sort_order']??0))<=>((int)($b['sort_order']??0));}); unset($group); $isAdmin=!empty($_SESSION['user_id'])&&($_SESSION['role']??'')==='ADMIN'; if(!$isAdmin){foreach($data as &$group) $group=array_values(array_filter($group,function($row){return !empty($row['is_active']);})); unset($group);} echo json_encode($data); exit; }
require_role('ADMIN'); $input=!empty($_POST)?$_POST:(json_decode(file_get_contents('php://input'),true)?:[]); $group=$input['group']??''; if(!isset($data[$group])||!in_array($group,['slides','ticker','central','provincial','featured'],true)) home_error('Invalid homepage content group.'); $action=$input['action']??'';
if($action==='delete') { $id=(int)($input['id']??0); $data[$group]=array_values(array_filter($data[$group],function($row)use($id){return (int)$row['id']!==$id;})); home_save($dataFile,$data); echo json_encode(['success'=>true]); exit; }
if(!in_array($action,['create','update'],true)) home_error('Unsupported action.');
$status = in_array(($input['status'] ?? ''), ['draft', 'published', 'scheduled', 'archived'], true) ? $input['status'] : (!empty($input['is_active']) ? 'published' : 'draft');
$record=['title'=>trim($input['title']??''),'date'=>trim($input['date']??''),'description'=>trim($input['description']??''),'image_url'=>trim($input['image_url']??''),'link_url'=>home_url($input['link_url']??''),'sort_order'=>max(1,(int)($input['sort_order']??1)),'is_active'=>!empty($input['is_active']),'status'=>$status];
$record['image_position_x']=max(0,min(100,(int)($input['image_position_x']??50))); $record['image_position_y']=max(0,min(100,(int)($input['image_position_y']??50)));
if($group==='slides'){$record=['title'=>$record['title'],'image_url'=>$record['image_url'],'sort_order'=>$record['sort_order'],'is_active'=>$record['is_active'],'status'=>$record['status'],'image_position_x'=>$record['image_position_x'],'image_position_y'=>$record['image_position_y']];}
$uploaded=home_upload('image',$uploadDir); if($uploaded!=='')$record['image_url']=$uploaded; if($record['title']==='')home_error('Title is required.'); if($action==='create'){ $ids=array_map(function($row){return(int)$row['id'];},$data[$group]);$record['id']=$ids?max($ids)+1:1;$data[$group][]=$record; } else { $id=(int)($input['id']??0);$found=false;foreach($data[$group] as &$row){if((int)$row['id']===$id){$record['id']=$id;$row=array_merge($row,$record);$found=true;break;}}unset($row);if(!$found)home_error('Homepage record not found.',404); } home_save($dataFile,$data); echo json_encode(['success'=>true,'record'=>$record]);
